-- Brew & Bite menu migration
-- Source: js/menu.js
-- This file is idempotent and safe to re-run.

CREATE UNIQUE INDEX IF NOT EXISTS ux_menu_items_name_category_price ON public.menu_items (name, category, price);


ON CONFLICT (name, category, price) DO UPDATE SET
  description = EXCLUDED.description,
  image_url = EXCLUDED.image_url,
  available = EXCLUDED.available,
  updated_at = now();